struct OperationSlot<T>(T);
impl<T: Default> Default for OperationSlot<T> {
    fn default() -> Self {
        Self(T::default())
    }
}
impl<T> OperationSlot<T> {
    fn with<R>(&self, use_slot: impl FnOnce(&T) -> R) -> R {
        use_slot(&self.0)
    }
}

/// Mutable host state for one operation.
#[derive(Default)]
#[allow(non_snake_case)]
pub struct OperationState {
    NATIVE_PROVIDER_CALL: OperationSlot<RefCell<Option<(String, String)>>>,
    INLINING_STACK: OperationSlot<RefCell<UnordSet<String>>>,
    OPERAND_ADMISSION_STACK: OperationSlot<RefCell<Vec<OperandAdmissionFacts>>>,
    TENSOR_HELPER_PREFLIGHT_STACK:
        OperationSlot<RefCell<Vec<UnordMap<usize, TensorHelperPreflightFacts>>>>,
    HOST_LOWER_DEPTH: OperationSlot<Cell<usize>>,
    HOST_LOWER_RED_ZONE: OperationSlot<Cell<usize>>,
    MONO_SPECIALIZATIONS: OperationSlot<RefCell<MonoSpecializationState>>,
    TOP_LEVEL_NAME_INDEX_BUILDS: OperationSlot<Cell<u64>>,
    ACTIVE_TYPE_SUBST: OperationSlot<RefCell<Vec<UnordMap<String, HostTypeTerm>>>>,
    ACTIVE_DIM_SUBST: OperationSlot<RefCell<Vec<UnordMap<String, DimInfo>>>>,
}
impl OperationState {
    pub fn active_native_provider_call(&self) -> Option<(String, String)> {
        self.NATIVE_PROVIDER_CALL.with(|slot| slot.borrow().clone())
    }

    pub fn with_native_provider_call<R>(
        &self,
        binding: Option<(String, String)>,
        lower: impl FnOnce() -> R,
    ) -> R {
        struct Restore<'a> {
            state: &'a OperationState,
            previous: Option<(String, String)>,
        }
        impl Drop for Restore<'_> {
            fn drop(&mut self) {
                self.state
                    .NATIVE_PROVIDER_CALL
                    .with(|slot| *slot.borrow_mut() = self.previous.take());
            }
        }
        let previous = self.NATIVE_PROVIDER_CALL.with(|slot| slot.replace(binding));
        let _restore = Restore {
            state: self,
            previous,
        };
        lower()
    }
}

fn native_provider_symbol<S: StackServices>(
    linked_name: &str,
    operation: &Operation<'_, S>,
) -> Option<String> {
    operation.host.NATIVE_PROVIDER_CALL.with(|slot| {
        slot.borrow()
            .as_ref()
            .and_then(|(name, symbol)| (name == linked_name).then(|| symbol.clone()))
    })
}

/// Borrowed lane selection. This view carries no native execution right.
pub trait ManifestView {
    fn len(&self) -> usize;
    fn is_empty(&self) -> bool {
        self.len() == 0
    }
    fn entry(&self, index: usize) -> ManifestEntry<'_>;
}

#[derive(Clone, Copy)]
pub struct ManifestEntry<'a> {
    pub def_name: &'a str,
    pub tensor_lane: bool,
}

// Host application lowering visits several Rust frames per Deep expression.
// Keep enough room to construct a located diagnostic and unwind that path.
const HOST_LOWER_STACK_RED_ZONE_MIN_BYTES: usize = 128 * 1024;
const HOST_LOWER_STACK_RED_ZONE_MAX_BYTES: usize = 8 * 1024 * 1024;
const HOST_LOWER_FALLBACK_MAX_DEPTH: usize = 8;

struct HostLowerStackFrame<'operation> {
    state: &'operation OperationState,
}

impl<'operation> HostLowerStackFrame<'operation> {
    fn enter<S: StackServices>(operation: &'operation Operation<'_, S>) -> Self {
        let outermost = operation.host.HOST_LOWER_DEPTH.with(|depth| {
            let outermost = depth.get() == 0;
            depth.set(depth.get() + 1);
            outermost
        });
        if outermost && let Some(remaining) = operation.resources.stack.remaining_stack() {
            let red_zone = (remaining / 4).clamp(
                HOST_LOWER_STACK_RED_ZONE_MIN_BYTES,
                HOST_LOWER_STACK_RED_ZONE_MAX_BYTES,
            );
            operation
                .host
                .HOST_LOWER_RED_ZONE
                .with(|zone| zone.set(red_zone));
        }
        Self {
            state: &operation.host,
        }
    }

    fn budget_exhausted<S: StackServices>(operation: &Operation<'_, S>) -> bool {
        match operation.resources.stack.remaining_stack() {
            Some(remaining) => operation
                .host
                .HOST_LOWER_RED_ZONE
                .with(|zone| remaining < zone.get()),
            None => operation
                .host
                .HOST_LOWER_DEPTH
                .with(|depth| depth.get() > HOST_LOWER_FALLBACK_MAX_DEPTH),
        }
    }
}

impl Drop for HostLowerStackFrame<'_> {
    fn drop(&mut self) {
        let outermost = self.state.HOST_LOWER_DEPTH.with(|depth| {
            depth.set(depth.get() - 1);
            depth.get() == 0
        });
        if outermost {
            self.state.HOST_LOWER_RED_ZONE.with(|zone| zone.set(0));
        }
    }
}

type HostDimensionOwners =
    PersistentMap<(core::cmp::Reverse<bool>, core::cmp::Reverse<String>), ()>;

/// Lexical host types share storage across nested scopes. All ordered exits
/// are explicit; input transport can read a name without copying its prefix.
#[derive(Default)]
pub(crate) struct HostScope {
    bindings: PersistentMap<String, HostTypeTerm>,
    dimension_labels: PersistentMap<String, HostDimensionOwners>,
    dimensions: PersistentMap<String, HostDimensionOwners>,
}

impl Clone for HostScope {
    fn clone(&self) -> Self {
        record_host_work(|profile| profile.host_scope_clones += 1);
        Self {
            bindings: self.bindings.clone(),
            dimensions: self.dimensions.clone(),
            dimension_labels: self.dimension_labels.clone(),
        }
    }
}

impl HostScope {
    pub(crate) fn new() -> Self {
        Self::default()
    }
    fn len(&self) -> usize {
        self.bindings.len()
    }
    #[cfg(test)]
    fn clear(&mut self) {
        *self = Self::default();
    }
    pub(crate) fn get(&self, name: &str) -> Option<&HostTypeTerm> {
        record_host_work(|profile| profile.host_scope_lookups += 1);
        self.bindings.get(name)
    }
    pub(crate) fn contains_key(&self, name: &str) -> bool {
        self.get(name).is_some()
    }
    fn dimension_names(ty: &HostTypeTerm) -> BTreeSet<String> {
        match ty {
            HostTypeTerm::Tensor(ty) => ty
                .dims
                .iter()
                .filter_map(|dim| match dim {
                    DimInfo::Named(name, _) => Some(name.clone()),
                    DimInfo::Lit(_) => None,
                })
                .collect(),
            _ => BTreeSet::new(),
        }
    }
    fn index_dimensions(&mut self, name: &str, names: BTreeSet<String>, add: bool) {
        let lexical = LoadStoreName::top_level_source_for_label(name)
            .ok()
            .flatten()
            .is_none();
        let key = (
            core::cmp::Reverse(lexical),
            core::cmp::Reverse(name.to_owned()),
        );
        for dim in names {
            for (index, label) in [
                (&mut self.dimensions, dim.clone()),
                (
                    &mut self.dimension_labels,
                    crate::lower::extent_binder_label(&dim),
                ),
            ] {
                record_host_work(|profile| profile.host_scope_bindings += 1);
                if add {
                    index
                        .get_or_insert_with(label, PersistentMap::new)
                        .insert(key.clone(), ());
                } else if let Some(owners) = index.get_mut(&label) {
                    owners.remove(&key);
                    if owners.is_empty() {
                        index.remove(&label);
                    }
                }
            }
        }
    }

    pub(crate) fn insert(&mut self, name: String, ty: HostTypeTerm) -> Option<HostTypeTerm> {
        if let Some(previous) = self.bindings.get(&name) {
            let before = Self::dimension_names(previous);
            self.index_dimensions(&name, before, false);
        }
        self.index_dimensions(&name, Self::dimension_names(&ty), true);
        record_host_work(|profile| profile.host_scope_bindings += 1);
        self.bindings.insert(name, ty)
    }
    fn remove(&mut self, name: &str) -> Option<HostTypeTerm> {
        if let Some(previous) = self.bindings.get(name) {
            let before = Self::dimension_names(previous);
            self.index_dimensions(name, before, false);
        }
        record_host_work(|profile| profile.host_scope_lookups += 1);
        self.bindings.remove(name)
    }
    #[track_caller]
    pub(crate) fn to_sorted(&self) -> Vec<(&String, &HostTypeTerm)> {
        record_host_work(|profile| profile.host_scope_transport_entries += self.len());
        self.bindings.to_sorted()
    }
    fn has_dimension(&self, name: &str) -> bool {
        record_host_work(|profile| profile.host_scope_lookups += 1);
        self.dimensions.contains_key(name)
    }
    fn dimension_source(&self, binder: &str) -> Option<(String, TensorType)> {
        // Wildcards reserve names but declare no named equality, as in the
        // ordered interface's parameter witness construction.
        if binder.is_empty() || binder == "*" {
            return None;
        }
        record_host_work(|profile| profile.host_scope_lookups += 2);
        let source = [&self.dimensions, &self.dimension_labels]
            .into_iter()
            .filter_map(|index| index.get(binder)?.last_where(|(lexical, _), _| lexical.0))
            .map(|(key, _)| &key.1.0)
            .min()?;
        Some((
            source.clone(),
            tensor_type_from_host_input(self.get(source)?)?,
        ))
    }
}

impl crate::lower::SignaturelessScope for HostScope {
    fn numeric_type(&self, name: &str) -> Option<TensorType> {
        if LoadStoreName::top_level_source_for_label(name)
            .ok()
            .flatten()
            .is_some()
        {
            return None;
        }
        tensor_type_from_host_input(self.get(name)?)
    }
    fn contains_lexical_name(&self, name: &str) -> bool {
        LoadStoreName::top_level_source_for_label(name)
            .ok()
            .flatten()
            .is_none()
            && self.contains_key(name)
    }
    fn host_payload_type(&self, name: &str) -> Option<HostTypeTerm> {
        if LoadStoreName::top_level_source_for_label(name)
            .ok()
            .flatten()
            .is_some()
        {
            return None;
        }
        self.get(name)
            .filter(|ty| tensor_helper_input_is_host_payload(ty))
            .cloned()
    }
    fn dimension_source(&self, binder: &str) -> Option<(String, TensorType)> {
        HostScope::dimension_source(self, binder)
    }
}

pub(crate) fn note_signatureless_scope_scan<S: StackServices>(
    expr: &Expr,
    _operation: &Operation<'_, S>,
) {
    record_host_work(|profile| profile.helper_scope_expr_nodes += deep_expr_nodes(expr));
}

pub(crate) fn note_signatureless_input_load<S: StackServices>(_operation: &Operation<'_, S>) {
    record_host_work(|profile| profile.helper_input_loads += 1);
}

pub(crate) fn note_signatureless_global_lookup<S: StackServices>(_operation: &Operation<'_, S>) {
    record_host_work(|profile| profile.helper_global_lookup_steps += 1);
}

impl Extend<(String, HostTypeTerm)> for HostScope {
    fn extend<T: IntoIterator<Item = (String, HostTypeTerm)>>(&mut self, iter: T) {
        for (name, ty) in iter {
            self.insert(name, ty);
        }
    }
}
impl FromIterator<(String, HostTypeTerm)> for HostScope {
    fn from_iter<T: IntoIterator<Item = (String, HostTypeTerm)>>(iter: T) -> Self {
        let mut scope = Self::new();
        scope.extend(iter);
        scope
    }
}
impl From<UnordMap<String, HostTypeTerm>> for HostScope {
    fn from(map: UnordMap<String, HostTypeTerm>) -> Self {
        record_host_work(|profile| profile.host_scope_transport_entries += map.len());
        map.into_sorted().into_iter().collect()
    }
}
impl<const N: usize> From<[(String, HostTypeTerm); N]> for HostScope {
    fn from(bindings: [(String, HostTypeTerm); N]) -> Self {
        bindings.into_iter().collect()
    }
}

impl core::ops::Index<&str> for HostScope {
    type Output = HostTypeTerm;
    fn index(&self, name: &str) -> &Self::Output {
        self.get(name).expect("bound host name")
    }
}

