#[cfg(test)]
mod match_arm_substitution_tests;

/// Exact nominal declaration identity of a checked host type. Backends
/// implement this view for their projected type carrier; runtime addresses and
/// dimensions do not participate in construction identity.
pub trait AccumulatorTypeIdentity {
    fn accumulator_nominal_identity(&self) -> Option<&str>;
    fn accumulator_type_matches(&self, expected: &HostTypeTerm) -> bool;
}
impl AccumulatorTypeIdentity for HostTypeTerm {
    fn accumulator_nominal_identity(&self) -> Option<&str> {
        match self {
            Self::Adt(name, _) => Some(name),
            _ => None,
        }
    }
    fn accumulator_type_matches(&self, expected: &HostTypeTerm) -> bool {
        self == expected
    }
}
impl AccumulatorTypeIdentity for ConcreteHostType {
    fn accumulator_nominal_identity(&self) -> Option<&str> {
        match self {
            Self::Adt(name, _) => Some(name),
            _ => None,
        }
    }
    fn accumulator_type_matches(&self, expected: &HostTypeTerm) -> bool {
        expected
            .clone()
            .into_concrete()
            .is_ok_and(|expected| self == &expected)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AccumulatorListOperation {
    Append,
    Concat,
}
impl AccumulatorListOperation {
    pub fn symbol(self) -> &'static str {
        match self {
            Self::Append => "append",
            Self::Concat => "concat",
        }
    }
}

/// Ordered structural evidence for components inherited from a callback's
/// original accumulator. Fresh components retain the ordinary next-entry walk.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AccumulatorDeltaRecipe {
    Fresh,
    Inherited,
    Constructor {
        owner: String,
        constructor: String,
        fields: Vec<AccumulatorDeltaRecipe>,
    },
    /// A fixed fresh prefix/suffix surrounds the complete inherited List.
    ListInterval {
        operation: AccumulatorListOperation,
        before: usize,
        after: usize,
    },
}

#[derive(Debug, Clone)]
pub struct AccumulatorDeltaProof {
    parameter: String,
    formal_type: HostTypeTerm,
    pattern: Arc<crate::claim_pattern::ClaimPattern>,
    recipe: AccumulatorDeltaRecipe,
}

impl AccumulatorDeltaProof {
    pub fn validates_formal_type<T: AccumulatorTypeIdentity>(&self, ty: &T) -> bool {
        ty.accumulator_type_matches(&self.formal_type)
    }
    pub fn validates_pattern(&self, pattern: &crate::claim_pattern::ClaimPattern) -> bool {
        self.pattern.as_ref() == pattern
    }
    pub fn parameter(&self) -> &str {
        &self.parameter
    }
    pub fn pattern(&self) -> &crate::claim_pattern::ClaimPattern {
        &self.pattern
    }
    pub fn recipe(&self) -> &AccumulatorDeltaRecipe {
        &self.recipe
    }
    pub fn has_extent_claim(&self) -> bool {
        self.pattern.nodes().iter().any(|node| matches!(node, crate::claim_pattern::ClaimNode::Tensor(tensor) if !tensor.axes.is_empty()))
    }
    /// A List recipe requires this exact builtin after lexical resolution.
    /// C validates its lowered Builtin identity; Eval uses its ordinary
    /// builtin-dispatch authority in the closure's captured frame.
    pub fn required_list_operation(&self) -> Option<AccumulatorListOperation> {
        match self.recipe {
            AccumulatorDeltaRecipe::ListInterval { operation, .. } => Some(operation),
            _ => None,
        }
    }

    /// Transport never turns this proof into an unchecked backend opt-out.
    pub fn validates_body<T: AccumulatorTypeIdentity>(&self, body: &HostExpr<T>) -> bool {
        self.validates_body_as(body, &self.parameter)
    }

    /// Validate the retained invocation's alpha-renamed formal. Consumers
    /// must additionally prove its entry value forwards the loop accumulator
    /// and that the original formal owns the identical obligation.
    pub fn validates_body_as<T: AccumulatorTypeIdentity>(
        &self,
        body: &HostExpr<T>,
        parameter: &str,
    ) -> bool {
        fn alias<T>(expr: &HostExpr<T>) -> Option<&str> {
            #[cfg(test)]
            charge_accumulator_identity_work(1);
            match &expr.kind {
                HostExprKind::Var(name, _) => Some(name),
                HostExprKind::FormalIngress { value, .. } => alias(value),
                _ => None,
            }
        }
        fn variable<T>(expr: &HostExpr<T>, aliases: &AccumulatorIdentities) -> bool {
            alias(expr).and_then(|name| aliases.role(name))
                == Some(AccumulatorRootRole::Accumulator)
        }
        fn validate<T: AccumulatorTypeIdentity>(
            expr: &HostExpr<T>,
            recipe: &AccumulatorDeltaRecipe,
            aliases: &mut AccumulatorIdentities,
        ) -> bool {
            #[cfg(test)]
            charge_accumulator_identity_work(1);
            match &expr.kind {
                HostExprKind::Let { bindings, body, .. }
                | HostExprKind::RetainedInvocation { bindings, body, .. } => {
                    let mut undo = Vec::with_capacity(bindings.len());
                    for binding in bindings {
                        let source = alias(&binding.value).and_then(|name| aliases.role(name));
                        let previous = aliases.bind(&binding.name, source);
                        undo.push((binding.name.as_str(), previous));
                    }
                    let valid = validate(body, recipe, aliases);
                    for (name, previous) in undo.into_iter().rev() {
                        aliases.restore(name, previous);
                    }
                    valid
                }
                HostExprKind::ResultClaimScope { body, .. } => validate(body, recipe, aliases),
                HostExprKind::ExtentSites { value, .. } => validate(value, recipe, aliases),
                _ => match recipe {
                    AccumulatorDeltaRecipe::Fresh => true,
                    AccumulatorDeltaRecipe::Inherited => variable(expr, aliases),
                    AccumulatorDeltaRecipe::Constructor {
                        owner,
                        constructor,
                        fields,
                    } => {
                        matches!(&expr.kind, HostExprKind::AdtConstruct { ctor, fields: actuals, ty }
                            if ty.accumulator_nominal_identity() == Some(owner.as_str()) && ctor == constructor && actuals.len() == fields.len()
                                && actuals.iter().zip(fields).all(|(actual, recipe)| validate(actual, recipe, aliases)))
                    }
                    AccumulatorDeltaRecipe::ListInterval {
                        operation,
                        before,
                        after,
                    } => {
                        let HostExprKind::Builtin { name, args, .. } = &expr.kind else {
                            return false;
                        };
                        if name.as_str() != operation.symbol() {
                            return false;
                        }
                        match (name.as_str(), args.as_slice(), *before, *after) {
                            ("append", [old, _], 0, 1) => variable(old, aliases),
                            ("concat", [old, fresh], 0, after) => {
                                variable(old, aliases)
                                    && matches!(&fresh.kind, HostExprKind::List(items, _) if items.len() == after)
                            }
                            ("concat", [fresh, old], before, 0) => {
                                variable(old, aliases)
                                    && matches!(&fresh.kind, HostExprKind::List(items, _) if items.len() == before)
                            }
                            _ => false,
                        }
                    }
                },
            }
        }
        validate(
            body,
            &self.recipe,
            &mut AccumulatorIdentities::new([(
                parameter.to_owned(),
                AccumulatorRootRole::Accumulator,
            )]),
        )
    }
}

/// Derive reuse evidence from the authored checked formal and construction,
/// never from runtime storage identity, equal extents, or inferred result types.
pub fn accumulator_delta_proof<S: StackServices>(
    expr: &Expr,
    registry: &chelis_checker_core::adt::AdtRegistry,
    operation: &Operation<'_, S>,
) -> Result<Option<AccumulatorDeltaProof>, crate::lower::LowerDiagnostic> {
    let Some((types, result)) = expr_fn_type(expr)? else {
        return Ok(None);
    };
    if types.first() != Some(&result) {
        return Ok(None);
    }
    accumulator_construction_proof_impl(expr, registry, None, false, operation)
}

/// A checked immutable construction postcondition is independent of the
/// function's declared result claim. In particular a wildcard result neither
/// proves nor invalidates reuse of the exact first formal's components.
pub fn accumulator_construction_proof<S: StackServices>(
    expr: &Expr,
    registry: &chelis_checker_core::adt::AdtRegistry,
    operation: &Operation<'_, S>,
) -> Result<Option<AccumulatorDeltaProof>, crate::lower::LowerDiagnostic> {
    accumulator_construction_proof_impl(expr, registry, None, true, operation)
}

/// Independent obligations composed through one exact direct forwarding call.
/// The caller must resolve `callee_name` by its checked lexical authority and
/// retain the exact callee definition; this proof does not resolve spellings.
#[derive(Debug, Clone)]
pub struct AccumulatorCompositionProof {
    callee_name: String,
    callsite: Expr,
    outer: Option<AccumulatorDeltaProof>,
    inner: AccumulatorDeltaProof,
    forwarding: AccumulatorForwardingPlan,
}

#[cfg(test)]
std::thread_local! {
    static ACCUMULATOR_IDENTITY_WORK: core::cell::Cell<usize> = const { core::cell::Cell::new(0) };
}

#[cfg(test)]
fn charge_accumulator_identity_work(units: usize) {
    ACCUMULATOR_IDENTITY_WORK.with(|work| work.set(work.get() + units));
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum AccumulatorRootRole {
    Accumulator,
    Item,
}

/// One lexical analysis frame. Deliberately not Clone: entering a Let records
/// only its changed bindings, and leaving restores them in reverse order.
struct AccumulatorIdentities<R = AccumulatorRootRole> {
    bindings: BTreeMap<String, Option<R>>,
}

impl<R: Copy> AccumulatorIdentities<R> {
    fn new(roots: impl IntoIterator<Item = (String, R)>) -> Self {
        let mut scope = Self {
            bindings: BTreeMap::new(),
        };
        for (name, role) in roots {
            scope.bind(&name, Some(role));
        }
        scope
    }
    fn role(&self, name: &str) -> Option<R> {
        #[cfg(test)]
        charge_accumulator_identity_work(1);
        self.bindings.get(name).copied().flatten()
    }
    fn is_bound(&self, name: &str) -> bool {
        #[cfg(test)]
        charge_accumulator_identity_work(1);
        self.bindings.contains_key(name)
    }
    fn bind(&mut self, name: &str, role: Option<R>) -> Option<Option<R>> {
        #[cfg(test)]
        charge_accumulator_identity_work(1);
        self.bindings.insert(name.to_owned(), role)
    }
    fn restore(&mut self, name: &str, previous: Option<Option<R>>) {
        #[cfg(test)]
        charge_accumulator_identity_work(1);
        if let Some(previous) = previous {
            self.bindings.insert(name.to_owned(), previous);
        } else {
            self.bindings.remove(name);
        }
    }
}

/// Whole immutable-variable identity is shared by construction and
/// forwarding proofs; metadata never creates a new binding occurrence.
fn accumulator_identity_variable(mut expr: &Expr) -> Option<&str> {
    #[cfg(test)]
    charge_accumulator_identity_work(1);
    while let Expr::MetaExpr(meta, _) = expr {
        #[cfg(test)]
        charge_accumulator_identity_work(1);
        expr = &meta.expr;
    }
    let node = as_node(expr).filter(|node| node.tag() == DeepTag::Var)?;
    node.children_slice().first().and_then(symbol_name)
}

/// One checked lexical occurrence path. A tail or exact returned-result
/// initializer may be selected; identical unselected calls cannot use it.
#[derive(Debug, Clone, PartialEq)]
pub struct AccumulatorForwardingPlan {
    callee_name: String,
    callsite: Expr,
    tails: Vec<ForwardingStep>,
    returned: Option<BoundAccumulatorForwardingPlan>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ForwardingStep {
    Tail(DeepTag),
    Initializer(usize),
}

impl AccumulatorForwardingPlan {
    pub fn callee_name(&self) -> &str {
        &self.callee_name
    }
    pub fn callsite(&self) -> &Expr {
        &self.callsite
    }
    pub fn is_target(&self, position: usize) -> bool {
        position == self.tails.len()
    }
    pub fn is_returned_invocation(&self) -> bool {
        self.returned.is_some()
    }
    pub fn initializer(&self, position: usize, layer: usize, ordinal: usize) -> Option<usize> {
        let position = self.advance(position, DeepTag::Let, layer)?;
        matches!(self.tails.get(position), Some(ForwardingStep::Initializer(index)) if *index == ordinal)
            .then_some(position + 1)
    }
    pub fn advance(&self, position: usize, tag: DeepTag, layers: usize) -> Option<usize> {
        let end = position.checked_add(layers)?;
        self.tails
            .get(position..end)?
            .iter()
            .all(|step| *step == ForwardingStep::Tail(tag))
            .then_some(end)
    }
}

fn tail_accumulator_forwarding_plan(callback: &Expr) -> Option<AccumulatorForwardingPlan> {
    fn bare(mut expr: &Expr) -> &Expr {
        while let Expr::MetaExpr(meta, _) = expr {
            expr = &meta.expr;
        }
        expr
    }
    let callback = as_node(bare(callback)).filter(|node| node.tag() == DeepTag::Fn)?;
    let params = as_node(callback.children_slice().first()?)?;
    let [acc, item] = params.children_slice() else {
        return None;
    };
    let acc = param_name(acc)?;
    let item = param_name(item)?;
    let mut roles = AccumulatorIdentities::new([
        (acc, AccumulatorRootRole::Accumulator),
        (item, AccumulatorRootRole::Item),
    ]);
    let mut tails = Vec::new();
    let mut current = callback.children_slice().get(1)?;
    loop {
        let node = as_node(bare(current))?;
        let children = node.children_slice();
        match node.tag() {
            DeepTag::Let => {
                let bindings = children.first().and_then(as_node)?;
                let (pairs, remainder) = bindings.children_slice().as_chunks::<2>();
                if bindings.tag() != DeepTag::Bind || !remainder.is_empty() {
                    return None;
                }
                for [binder, initializer] in pairs {
                    let role = accumulator_identity_variable(initializer)
                        .and_then(|name| roles.role(name));
                    let mut names = UnordSet::new();
                    collect_binder_names(binder, &mut names);
                    for name in names.into_sorted() {
                        roles.bind(&name, None);
                    }
                    if let (Some(role), Some(name)) = (role, symbol_name(binder)) {
                        roles.bind(name, Some(role));
                    }
                }
                tails.push(ForwardingStep::Tail(DeepTag::Let));
                current = children.get(1)?;
            }
            DeepTag::Block => {
                tails.push(ForwardingStep::Tail(DeepTag::Block));
                current = children.last()?;
            }
            DeepTag::App => {
                let [function, first, second] = children else {
                    return None;
                };
                if function.tag() != Some(DeepTag::Var) {
                    return None;
                }
                let callee = accumulator_identity_variable(function)?;
                if roles.is_bound(callee)
                    || roles.role(accumulator_identity_variable(first)?)
                        != Some(AccumulatorRootRole::Accumulator)
                    || roles.role(accumulator_identity_variable(second)?)
                        != Some(AccumulatorRootRole::Item)
                {
                    return None;
                }
                return Some(AccumulatorForwardingPlan {
                    callee_name: callee.to_owned(),
                    callsite: bare(current).clone(),
                    tails,
                    returned: None,
                });
            }
            _ => return None,
        }
    }
}

/// Structural edges from the original checked callback body to one invocation.
/// Ordinals identify source binding occurrences, never binder spellings/spans.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BoundForwardingEdge {
    Metadata,
    LetInitializer(usize),
    LetBody,
    BlockTail,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum BoundForwardingRole {
    Original(AccumulatorRootRole),
    InvocationResult(usize),
}

/// Static lineage alone cannot authorize an entry receipt. Executors also
/// validate the selected lowered region, returned-value link and each owning
/// obligation before enabling reuse.
#[derive(Debug, Clone, PartialEq)]
pub struct BoundAccumulatorForwardingPlan {
    owner: Expr,
    occurrence: usize,
    callee_name: String,
    callsite: Expr,
    route: Vec<BoundForwardingEdge>,
    candidate_count: usize,
    route_records: usize,
}

impl BoundAccumulatorForwardingPlan {
    pub fn owner(&self) -> &Expr {
        &self.owner
    }
    pub fn occurrence(&self) -> usize {
        self.occurrence
    }
    pub fn callee_name(&self) -> &str {
        &self.callee_name
    }
    pub fn callsite(&self) -> &Expr {
        &self.callsite
    }
    pub fn route(&self) -> &[BoundForwardingEdge] {
        &self.route
    }
    pub fn analysis_records(&self) -> (usize, usize) {
        (self.candidate_count, self.route_records)
    }
}

/// Prove only static returned-value lineage. No runtime value, inferred shape,
/// callback/callee obligation or capture authority is supplied by this walk.
pub fn bound_accumulator_forwarding_plan<S: StackServices>(
    callback: &Expr,
    _operation: &Operation<'_, S>,
) -> Result<Option<BoundAccumulatorForwardingPlan>, crate::lower::LowerDiagnostic> {
    struct RouteRecord {
        parent: Option<usize>,
        edge: BoundForwardingEdge,
    }
    struct Candidate {
        route: Option<usize>,
        callee_name: String,
        callsite: Expr,
    }
    struct Walk {
        routes: Vec<RouteRecord>,
        candidates: Vec<Candidate>,
    }
    impl Walk {
        fn edge(&mut self, parent: Option<usize>, edge: BoundForwardingEdge) -> Option<usize> {
            #[cfg(test)]
            charge_accumulator_identity_work(1);
            let index = self.routes.len();
            self.routes.push(RouteRecord { parent, edge });
            Some(index)
        }
        fn value(
            &mut self,
            expr: &Expr,
            parent: Option<usize>,
            roles: &mut AccumulatorIdentities<BoundForwardingRole>,
        ) -> Option<BoundForwardingRole> {
            struct LetState<'a> {
                pairs: &'a [[Expr; 2]],
                ordinal: usize,
                body: &'a Expr,
                parent: Option<usize>,
                undo: Vec<(String, Option<Option<BoundForwardingRole>>)>,
            }
            enum Task<'a> {
                Value(&'a Expr, Option<usize>),
                Next(LetState<'a>),
                Bind(LetState<'a>),
                Restore(Vec<(String, Option<Option<BoundForwardingRole>>)>),
            }
            let mut tasks = vec![Task::Value(expr, parent)];
            let mut result = None;
            while let Some(task) = tasks.pop() {
                #[cfg(test)]
                charge_accumulator_identity_work(1);
                match task {
                    Task::Next(state) => {
                        if let Some([_, initializer]) = state.pairs.get(state.ordinal) {
                            let next = self.edge(
                                state.parent,
                                BoundForwardingEdge::LetInitializer(state.ordinal),
                            );
                            tasks.push(Task::Bind(state));
                            tasks.push(Task::Value(initializer, next));
                        } else {
                            let next = self.edge(state.parent, BoundForwardingEdge::LetBody);
                            tasks.push(Task::Restore(state.undo));
                            tasks.push(Task::Value(state.body, next));
                        }
                    }
                    Task::Bind(mut state) => {
                        let [binder, _] = &state.pairs[state.ordinal];
                        let mut names = UnordSet::new();
                        collect_binder_names(binder, &mut names);
                        for name in names.into_sorted() {
                            let previous = roles.bind(&name, None);
                            state.undo.push((name, previous));
                        }
                        if let (Some(role), Some(name)) = (result, symbol_name(binder)) {
                            let previous = roles.bind(name, Some(role));
                            state.undo.push((name.to_owned(), previous));
                        }
                        state.ordinal += 1;
                        tasks.push(Task::Next(state));
                    }
                    Task::Restore(undo) => {
                        for (name, previous) in undo.into_iter().rev() {
                            roles.restore(&name, previous);
                        }
                    }
                    Task::Value(expr, parent) => {
                        result = None;
                        if let Expr::MetaExpr(meta, _) = expr {
                            let next = self.edge(parent, BoundForwardingEdge::Metadata);
                            tasks.push(Task::Value(&meta.expr, next));
                            continue;
                        }
                        let Some(node) = as_node(expr) else {
                            continue;
                        };
                        let children = node.children_slice();
                        match node.tag() {
                            DeepTag::Var => {
                                result = accumulator_identity_variable(expr)
                                    .and_then(|name| roles.role(name));
                            }
                            DeepTag::App => {
                                let [function, first, second] = children else {
                                    continue;
                                };
                                if function.tag() != Some(DeepTag::Var) {
                                    continue;
                                }
                                let Some(callee) = accumulator_identity_variable(function) else {
                                    continue;
                                };
                                let first = accumulator_identity_variable(first)
                                    .and_then(|name| roles.role(name));
                                let second = accumulator_identity_variable(second)
                                    .and_then(|name| roles.role(name));
                                if roles.is_bound(callee)
                                    || first
                                        != Some(BoundForwardingRole::Original(
                                            AccumulatorRootRole::Accumulator,
                                        ))
                                    || second
                                        != Some(BoundForwardingRole::Original(
                                            AccumulatorRootRole::Item,
                                        ))
                                {
                                    continue;
                                }
                                let occurrence = self.candidates.len();
                                self.candidates.push(Candidate {
                                    route: parent,
                                    callee_name: callee.to_owned(),
                                    callsite: expr.clone(),
                                });
                                result = Some(BoundForwardingRole::InvocationResult(occurrence));
                            }
                            DeepTag::Let => {
                                let bindings = children.first().and_then(as_node)?;
                                let (pairs, remainder) = bindings.children_slice().as_chunks::<2>();
                                if bindings.tag() != DeepTag::Bind || !remainder.is_empty() {
                                    return None;
                                }
                                tasks.push(Task::Next(LetState {
                                    pairs,
                                    ordinal: 0,
                                    body: children.get(1)?,
                                    parent,
                                    undo: Vec::new(),
                                }));
                            }
                            DeepTag::Block => {
                                if let Some(tail) = children.last() {
                                    let next = self.edge(parent, BoundForwardingEdge::BlockTail);
                                    tasks.push(Task::Value(tail, next));
                                }
                            }
                            _ => {}
                        }
                    }
                }
            }
            result
        }
    }
    let mut callback_node = callback;
    while let Expr::MetaExpr(meta, _) = callback_node {
        callback_node = &meta.expr;
    }
    let Some(node) = as_node(callback_node).filter(|node| node.tag() == DeepTag::Fn) else {
        return Ok(None);
    };
    let Some((types, _)) = expr_fn_type(callback)? else {
        return Ok(None);
    };
    if types.len() != 2 || !matches!(types[1], HostTypeTerm::Scalar(_) | HostTypeTerm::Unit) {
        return Ok(None);
    }
    Ok((|| {
        let params = as_node(node.children_slice().first()?)?;
        let [acc, item] = params.children_slice() else {
            return None;
        };
        let mut roles = AccumulatorIdentities::new([
            (
                param_name(acc)?,
                BoundForwardingRole::Original(AccumulatorRootRole::Accumulator),
            ),
            (
                param_name(item)?,
                BoundForwardingRole::Original(AccumulatorRootRole::Item),
            ),
        ]);
        let mut walk = Walk {
            routes: Vec::new(),
            candidates: Vec::new(),
        };
        let BoundForwardingRole::InvocationResult(occurrence) =
            walk.value(node.children_slice().get(1)?, None, &mut roles)?
        else {
            return None;
        };
        let selected = walk.candidates.get(occurrence)?;
        let mut current = selected.route;
        let mut route = Vec::new();
        while let Some(index) = current {
            #[cfg(test)]
            charge_accumulator_identity_work(1);
            let record = walk.routes.get(index)?;
            route.push(record.edge);
            current = record.parent;
        }
        route.reverse();
        Some(BoundAccumulatorForwardingPlan {
            owner: callback.clone(),
            occurrence,
            callee_name: selected.callee_name.clone(),
            callsite: selected.callsite.clone(),
            route,
            candidate_count: walk.candidates.len(),
            route_records: walk.routes.len(),
        })
    })())
}

pub fn accumulator_forwarding_plan<S: StackServices>(
    callback: &Expr,
    operation: &Operation<'_, S>,
) -> Result<Option<AccumulatorForwardingPlan>, crate::lower::LowerDiagnostic> {
    if let Some(plan) = tail_accumulator_forwarding_plan(callback) {
        return Ok(Some(plan));
    }
    Ok(
        bound_accumulator_forwarding_plan(callback, operation)?.map(|returned| {
            let tails = returned
                .route
                .iter()
                .filter_map(|edge| match edge {
                    BoundForwardingEdge::Metadata => None,
                    BoundForwardingEdge::LetInitializer(index) => {
                        Some(ForwardingStep::Initializer(*index))
                    }
                    BoundForwardingEdge::LetBody => Some(ForwardingStep::Tail(DeepTag::Let)),
                    BoundForwardingEdge::BlockTail => Some(ForwardingStep::Tail(DeepTag::Block)),
                })
                .collect();
            AccumulatorForwardingPlan {
                callee_name: returned.callee_name.clone(),
                callsite: returned.callsite.clone(),
                tails,
                returned: Some(returned),
            }
        }),
    )
}

/// Independently validate a lowered callback's whole returned-value link.
/// A source marker selects one immutable IR occurrence; it does not validate
/// its callee recipe, signature or staged arguments. Consumers retain those
/// separate checks before enabling any entry reuse.
pub fn returned_accumulator_invocation<'a, T>(
    body: &'a HostExpr<T>,
    plan: &AccumulatorForwardingPlan,
) -> Option<&'a HostExpr<T>> {
    if !plan.is_returned_invocation() {
        return None;
    }
    struct LetState<'a, T> {
        bindings: &'a [HostBinding<T>],
        ordinal: usize,
        body: &'a HostExpr<T>,
        undo: Vec<(String, Option<Option<bool>>)>,
    }
    enum Task<'a, T> {
        Value(&'a HostExpr<T>),
        Next(LetState<'a, T>),
        Bind(LetState<'a, T>),
        Restore(Vec<(String, Option<Option<bool>>)>),
    }
    let mut roles = AccumulatorIdentities::new(core::iter::empty::<(String, bool)>());
    let mut tasks = vec![Task::Value(body)];
    let mut result = None;
    let mut selected = None;
    let mut occurrences = 0;
    while let Some(task) = tasks.pop() {
        #[cfg(test)]
        charge_accumulator_identity_work(1);
        match task {
            Task::Next(state) => {
                if let Some(binding) = state.bindings.get(state.ordinal) {
                    tasks.push(Task::Bind(state));
                    tasks.push(Task::Value(&binding.value));
                } else {
                    tasks.push(Task::Restore(state.undo));
                    tasks.push(Task::Value(state.body));
                }
            }
            Task::Bind(mut state) => {
                let binding = &state.bindings[state.ordinal];
                let previous = roles.bind(&binding.name, result);
                state.undo.push((binding.name.clone(), previous));
                state.ordinal += 1;
                tasks.push(Task::Next(state));
            }
            Task::Restore(undo) => {
                for (name, previous) in undo.into_iter().rev() {
                    roles.restore(&name, previous);
                }
            }
            Task::Value(value) => {
                result = None;
                match &value.kind {
                    HostExprKind::RetainedInvocation { forwarding, .. }
                        if forwarding.as_deref() == Some(plan) =>
                    {
                        occurrences += 1;
                        selected = Some(value);
                        result = Some(true);
                    }
                    HostExprKind::Var(name, _) => result = roles.role(name),
                    HostExprKind::Let { bindings, body, .. } => {
                        tasks.push(Task::Next(LetState {
                            bindings,
                            ordinal: 0,
                            body,
                            undo: Vec::new(),
                        }));
                    }
                    HostExprKind::ResultClaimScope { body, .. }
                    | HostExprKind::ExtentSites { value: body, .. }
                    | HostExprKind::FormalIngress { value: body, .. } => {
                        tasks.push(Task::Value(body));
                    }
                    _ => {}
                }
            }
        }
    }
    let selected = selected?;
    (result == Some(true) && occurrences == 1).then_some(selected)
}

impl AccumulatorCompositionProof {
    pub fn callee_name(&self) -> &str {
        &self.callee_name
    }
    pub fn callsite(&self) -> &Expr {
        &self.callsite
    }
    pub fn outer(&self) -> Option<&AccumulatorDeltaProof> {
        self.outer.as_ref()
    }
    pub fn inner(&self) -> &AccumulatorDeltaProof {
        &self.inner
    }
    pub fn forwarding(&self) -> &AccumulatorForwardingPlan {
        &self.forwarding
    }
}

pub fn accumulator_composition_proof<S: StackServices>(
    callback: &Expr,
    callee: &Expr,
    registry: &chelis_checker_core::adt::AdtRegistry,
    operation: &Operation<'_, S>,
) -> Result<Option<AccumulatorCompositionProof>, crate::lower::LowerDiagnostic> {
    fn bare(expr: &Expr) -> &Expr {
        match expr {
            Expr::MetaExpr(meta, _) => bare(&meta.expr),
            _ => expr,
        }
    }
    let Some(callback_node) = as_node(bare(callback)).filter(|node| node.tag() == DeepTag::Fn)
    else {
        return Ok(None);
    };
    let Some(params) = callback_node.children_slice().first().and_then(as_node) else {
        return Ok(None);
    };
    let [acc, _item] = params.children_slice() else {
        return Ok(None);
    };
    let Some((types, _)) = expr_fn_type(callback)? else {
        return Ok(None);
    };
    if types.len() != 2 || !matches!(types[1], HostTypeTerm::Scalar(_) | HostTypeTerm::Unit) {
        return Ok(None);
    }
    let Some(forwarding) = accumulator_forwarding_plan(callback, operation)? else {
        return Ok(None);
    };
    let Some(parameter) = param_name(acc) else {
        return Ok(None);
    };
    let Some(authored) = param_declared_type_expr(acc) else {
        return Ok(None);
    };
    let outer = match accumulator_construction_proof_impl(
        callee,
        registry,
        Some(&authored),
        true,
        operation,
    )? {
        Some(mut proof) => {
            proof.parameter = parameter;
            Some(proof)
        }
        None => {
            let Ok(claims) = crate::claim_pattern::ClaimPattern::derive(&authored, registry) else {
                return Ok(None);
            };
            let Ok(admission) =
                crate::claim_pattern::ClaimPattern::derive_admission(&authored, registry)
            else {
                return Ok(None);
            };
            if !claims.is_empty() || admission.is_empty() || admission.nodes().iter().any(|node|
                matches!(node, crate::claim_pattern::ClaimNode::Tensor(tensor) if tensor.rank.is_none()
                    || !matches!(decode_host_type(&tensor.ty), Ok(HostTypeTerm::Tensor(_))))) {
                return Ok(None);
            }
            None
        }
    };
    let Some(inner) = accumulator_construction_proof(callee, registry, operation)? else {
        return Ok(None);
    };
    Ok(Some(AccumulatorCompositionProof {
        callee_name: forwarding.callee_name.clone(),
        callsite: forwarding.callsite.clone(),
        outer,
        inner,
        forwarding,
    }))
}

fn accumulator_construction_proof_impl<S: StackServices>(
    expr: &Expr,
    registry: &chelis_checker_core::adt::AdtRegistry,
    forwarded_formal: Option<&Expr>,
    admission: bool,
    operation: &Operation<'_, S>,
) -> Result<Option<AccumulatorDeltaProof>, crate::lower::LowerDiagnostic> {
    use crate::claim_pattern::{ClaimNode, ClaimNodeId, ClaimPattern};
    fn variable(expr: &Expr, aliases: &AccumulatorIdentities) -> bool {
        accumulator_identity_variable(expr).and_then(|name| aliases.role(name))
            == Some(AccumulatorRootRole::Accumulator)
    }
    fn recipe<S: StackServices>(
        expr: &Expr,
        parameter: &str,
        pattern: &ClaimPattern,
        position: ClaimNodeId,
        root: ClaimNodeId,
        aliases: &mut AccumulatorIdentities,
        operation: &Operation<'_, S>,
    ) -> Result<Option<(AccumulatorDeltaRecipe, bool)>, crate::lower::LowerDiagnostic> {
        #[cfg(test)]
        charge_accumulator_identity_work(1);
        if let Expr::MetaExpr(meta, _) = expr {
            return recipe(
                &meta.expr, parameter, pattern, position, root, aliases, operation,
            );
        }
        let Some(node) = as_node(expr) else {
            return Ok(None);
        };
        let children = node.children_slice();
        if variable(expr, aliases) {
            return Ok((position == root).then_some((AccumulatorDeltaRecipe::Inherited, true)));
        }
        match node.tag() {
            DeepTag::Block => {
                let Some(tail) = children.last() else {
                    return Ok(None);
                };
                recipe(tail, parameter, pattern, position, root, aliases, operation)
            }
            DeepTag::Let => {
                let Some(bindings) = children.first().and_then(as_node) else {
                    return Ok(None);
                };
                let (pairs, remainder) = bindings.children_slice().as_chunks::<2>();
                if bindings.tag() != DeepTag::Bind || !remainder.is_empty() {
                    return Ok(None);
                }
                let mut undo = Vec::new();
                let result = (|| {
                    for [binder, initializer] in pairs {
                        let role = accumulator_identity_variable(initializer)
                            .and_then(|name| aliases.role(name));
                        let mut names = UnordSet::new();
                        collect_binder_names(binder, &mut names);
                        if names.contains(parameter) {
                            return Ok(None);
                        }
                        for name in names.into_sorted() {
                            let previous = aliases.bind(&name, None);
                            undo.push((name, previous));
                        }
                        if let (Some(role), Some(name)) = (role, symbol_name(binder)) {
                            let previous = aliases.bind(name, Some(role));
                            undo.push((name.to_owned(), previous));
                        }
                    }
                    let Some(body) = children.get(1) else {
                        return Ok(None);
                    };
                    recipe(body, parameter, pattern, position, root, aliases, operation)
                })();
                for (name, previous) in undo.into_iter().rev() {
                    aliases.restore(&name, previous);
                }
                result
            }
            DeepTag::Record => {
                let ClaimNode::Nominal {
                    name: owner,
                    constructors,
                } = pattern.node(position)
                else {
                    return Ok(Some((AccumulatorDeltaRecipe::Fresh, false)));
                };
                if !matches!(expr_type(expr, operation)?, Some(HostTypeTerm::Adt(name, _)) if name == *owner)
                {
                    return Ok(None);
                }
                let Some(name) = children.first().and_then(symbol_name) else {
                    return Ok(None);
                };
                let Some(constructor) = constructors
                    .iter()
                    .find(|constructor| constructor.name == name)
                else {
                    return Ok(None);
                };
                let mut fields = Vec::with_capacity(constructor.fields.len());
                let mut reused = false;
                for field in &constructor.fields {
                    let Some(child) = field.node else {
                        fields.push(AccumulatorDeltaRecipe::Fresh);
                        continue;
                    };
                    let Some(source) = children.iter().skip(1).find_map(|expr| {
                        let kv = as_node(expr)?;
                        (kv.tag() == DeepTag::Kv
                            && kv.children_slice().first().and_then(symbol_name)
                                == field.name.as_deref())
                        .then(|| kv.children_slice().get(1))
                        .flatten()
                    }) else {
                        return Ok(None);
                    };
                    let Some((part, inherits)) =
                        recipe(source, parameter, pattern, child, root, aliases, operation)?
                    else {
                        return Ok(None);
                    };
                    reused |= inherits;
                    fields.push(part);
                }
                Ok(Some((
                    AccumulatorDeltaRecipe::Constructor {
                        owner: owner.clone(),
                        constructor: name.to_owned(),
                        fields,
                    },
                    reused,
                )))
            }
            DeepTag::App
                if position == root
                    && matches!(pattern.node(root), ClaimNode::List(child) if matches!(pattern.node(*child), ClaimNode::Tensor(_))) =>
            {
                let Some(callee) = children.first().and_then(as_node) else {
                    return Ok(None);
                };
                if callee.tag() != DeepTag::Var {
                    return Ok(Some((AccumulatorDeltaRecipe::Fresh, false)));
                }
                let Some(name) = callee.children_slice().first().and_then(symbol_name) else {
                    return Ok(None);
                };
                if aliases.is_bound(name) {
                    return Ok(None);
                }
                fn length(expr: &Expr) -> Option<usize> {
                    if let Expr::MetaExpr(meta, _) = expr {
                        return length(&meta.expr);
                    }
                    let mut spine = ConsSpine::with_metadata_wrappers(expr);
                    let length = spine.by_ref().count();
                    spine.require_nil().ok()?;
                    Some(length)
                }
                let result = match (name, &children[1..]) {
                    ("append", [old, _]) if variable(old, aliases) => Some((0, 1)),
                    ("concat", [old, fresh]) if variable(old, aliases) => {
                        length(fresh).map(|after| (0, after))
                    }
                    ("concat", [fresh, old]) if variable(old, aliases) => {
                        length(fresh).map(|before| (before, 0))
                    }
                    _ => None,
                };
                Ok(Some(result.map_or(
                    (AccumulatorDeltaRecipe::Fresh, false),
                    |(before, after)| {
                        (
                            AccumulatorDeltaRecipe::ListInterval {
                                operation: if name == "append" {
                                    AccumulatorListOperation::Append
                                } else {
                                    AccumulatorListOperation::Concat
                                },
                                before,
                                after,
                            },
                            true,
                        )
                    },
                )))
            }
            _ => Ok(Some((AccumulatorDeltaRecipe::Fresh, false))),
        }
    }
    if let Expr::MetaExpr(meta, _) = expr {
        return accumulator_construction_proof_impl(
            &meta.expr,
            registry,
            forwarded_formal,
            admission,
            operation,
        );
    }
    let Some(node) = as_node(expr).filter(|node| node.tag() == DeepTag::Fn) else {
        return Ok(None);
    };
    let Some(params) = node
        .children_slice()
        .first()
        .and_then(as_node)
        .filter(|node| node.tag() == DeepTag::Params)
    else {
        return Ok(None);
    };
    let [acc, _] = params.children_slice() else {
        return Ok(None);
    };
    let Some((types, _)) = expr_fn_type(expr)? else {
        return Ok(None);
    };
    if types.len() != 2 || !matches!(types[1], HostTypeTerm::Scalar(_) | HostTypeTerm::Unit) {
        return Ok(None);
    }
    let Some(declared) = param_declared_type_expr(acc) else {
        return Ok(None);
    };
    let authored = forwarded_formal.unwrap_or(&declared);
    let Ok(mut pattern) = ClaimPattern::derive(authored, registry) else {
        return Ok(None);
    };
    if admission
        && pattern.is_empty()
        && matches!(decode_host_type(authored), Ok(HostTypeTerm::List(element)) if matches!(*element, HostTypeTerm::Tensor(_)))
    {
        let Ok(admitted) = ClaimPattern::derive_admission(authored, registry) else {
            return Ok(None);
        };
        pattern = admitted;
    }
    if pattern.nodes().iter().any(|node| matches!(node, ClaimNode::Tensor(tensor)
        if tensor.rank.is_none() || !matches!(decode_host_type(&tensor.ty), Ok(HostTypeTerm::Tensor(_))))) {
        return Ok(None);
    }
    let Some(root) = pattern.nested_root() else {
        return Ok(None);
    };
    let Some(parameter) = param_name(acc) else {
        return Ok(None);
    };
    let Some(body) = node.children_slice().get(1) else {
        return Ok(None);
    };
    let Some((recipe, reused)) = recipe(
        body,
        &parameter,
        &pattern,
        root,
        root,
        &mut AccumulatorIdentities::new([(parameter.clone(), AccumulatorRootRole::Accumulator)]),
        operation,
    )?
    else {
        return Ok(None);
    };
    let Ok(formal_type) = decode_host_type(authored) else {
        return Ok(None);
    };
    let formal_type = normalize_host_type(registry, formal_type, operation)?;
    Ok(
        (reused && (admission || !matches!(recipe, AccumulatorDeltaRecipe::Inherited))).then_some(
            AccumulatorDeltaProof {
                parameter,
                formal_type,
                pattern: Arc::new(pattern),
                recipe,
            },
        ),
    )
}

